using System.Text.Json;
using VisionFramework;
using VisionPluginContracts;
namespace VisionPlugins.BranchString;
internal static class BranchStringConfiguration {
 public static ToolConfigurationSession Create(ToolEditorContext context,ModuleDescriptor descriptor){const string language="Chinese";var words=JsonSerializer.Deserialize<Dictionary<string,string>>(BranchStringPlugin.Resource("BranchStringLocalization.json"))??[];string Text(string key)=>words.GetValueOrDefault(key)??ConfigurationLocalization.ForLanguage(language).Get(key);var definition=ToolConfigurationDefinition.Parse(BranchStringPlugin.Resource("BranchStringCpmLAlgorithmTab.xml"));var values=descriptor.Parameters.ToDictionary(p=>p.Name,p=>p.DefaultValue!.Value.Clone());foreach(var p in context.Node.Parameters)values[p.Key]=p.Value.Clone();Dictionary<string,JsonElement> Read(){if(context.ReadEffectiveParameters?.Invoke() is {} effective)foreach(var p in effective)if(values.ContainsKey(p.Key))values[p.Key]=p.Value.Clone();return values;}void Apply(Dictionary<string,JsonElement> next){context.Apply(next.ToDictionary(p=>p.Key,p=>p.Value.Clone()));values=next;}var adapter=new ToolConfigurationParameterAdapter(descriptor,Read,Apply);ToolConfigurationState? state=null;ToolConfigurationSession? session=null;
  var dispatch=new Dispatcher(request=>{
   if(request.Kind==ConfigurationOperationKind.WriteParameter&&request.Source.Name=="ModuleInfoList"){var next=Read().ToDictionary(p=>p.Key,p=>p.Value.Clone());next["ModuleInfoList"]=JsonSerializer.SerializeToElement(BranchStringTable.Serialize(BranchStringTable.ApplySetter(request.Value)));Apply(next);return new(true,request.Value??"");}
   if(request.Kind==ConfigurationOperationKind.EnumerateInputs){var query=ConfigurationSubscriptionValidation.FromElement(request.Source.Element);if(query is null||context.ConfigurationSubscriptions is null)return new(true,Error:"Source string subscription service is unavailable.");var tree=context.ConfigurationSubscriptions.Enumerate(query);return new(true,Error:tree.Status==ConfigurationSubscriptionStatus.Available?null:tree.Diagnostic??tree.Status.ToString()){SubscriptionTree=tree};}
   if(request.Kind is ConfigurationOperationKind.ReadInputBinding or ConfigurationOperationKind.WriteInputBinding){var query=ConfigurationSubscriptionValidation.FromElement(request.Source.Element);if(query is null||context.ConfigurationSubscriptions is null)return new(true,Error:"Source string subscription service is unavailable.");var result=request.Kind==ConfigurationOperationKind.WriteInputBinding?context.ConfigurationSubscriptions.Bind(query.Destination,request.SubscriptionBinding):context.ConfigurationSubscriptions.Read(query.Destination);if(result.Status!=ConfigurationSubscriptionStatus.Available)return new(true,Error:result.Diagnostic??result.Status.ToString());if(!state!.ApplySubscription(request.Source,result,false))return new(true,Error:"Subscription identity/presentation was not confirmed.");return new(true,result.DisplayText??"");}
   if(request.Kind==ConfigurationOperationKind.Close){session?.RequestClose();return new(true);}return adapter.Dispatch(request);
  });state=new(definition,dispatch);var controls=new ToolConfigurationControlRegistry();ToolConfigurationStandardControls.Register(controls,Text,language:language,subscriptions:context.ConfigurationSubscriptions);ToolConfigurationSubscriptionControls.Register(controls,context.ConfigurationSubscriptions,Text,language);BranchStringControls.Register(controls,Text);session=new(state,controls,language,Text);state.Initialize();return session;
 }
 sealed class Dispatcher(Func<ConfigurationOperationRequest,ConfigurationOperationResult> callback):IToolConfigurationDispatcher{public ConfigurationOperationResult Dispatch(ConfigurationOperationRequest request)=>callback(request);}
}
